script:
//
// Tell autoloader where to find language components
Prism.plugins.autoloader.languages_path = 'https://cdn.jsdelivr.net/npm/prismjs@1.29.0/components/';
//

//
document.addEventListener("DOMContentLoaded", function() {
  // Render WordPress KaTeX blocks (display mode)
  document.querySelectorAll('.wp-block-katex-display-block pre').forEach(function(el) {
    katex.render(el.textContent, el.parentNode, {
      displayMode: true,
      throwOnError: false
    });
  });
  // Render WordPress KaTeX inline blocks
  document.querySelectorAll('.wp-block-katex-inline-block').forEach(function(el) {
    katex.render(el.textContent, el, {
      displayMode: false,
      throwOnError: false
    });
  });
  // Also handle $$ and \( \) for any new posts written directly in Blogger
  if (typeof renderMathInElement !== 'undefined') {
    renderMathInElement(document.body, {
      delimiters: [
        {left: "$$", right: "$$", display: true},
        {left: "\(", right: "\)", display: false},
        {left: "\[", right: "\]", display: true}
      ],
      throwOnError: false
    });
  }
});
//
